s='E_GHEI_GELK__OME'
def fill(o):
    it=iter(o); return ''.join(next(it) if c=='_' else c for c in s)
def ok(t):
    g=[t[i:i+4] for i in range(0,16,4)]
    if any(x[0]!='E' for x in g): return False
    for p,d in ((1,3),(2,2),(3,-1)):
        if any(ord(g[i+1][p])-ord(g[i][p])!=d for i in range(3)): return False
    return True
opts={'A':'IFGE','B':'IGFE','C':'FIFE','D':'FGEI'}
assert [k for k,v in opts.items() if ok(fill(v))]==['C']

